import { PDFDocument, PDFForm, PDFTextField } from 'npm:pdf-lib@1.17.1';

/**
 * The blank form lives in the site's own assets (src/assets/forms), not in Supabase
 * Storage. It used to sit in a Storage bucket, which meant the only copy of it was
 * inside one Supabase project — when that project was paused the template became
 * unreachable and there was nothing in git to restore it from. Served from Netlify's
 * CDN it is versioned with the code and survives any future Supabase change.
 *
 * Its fields are generated by scripts/membership-form/build.ts, which also holds the
 * field names filled below.
 */
export const PDF_FORM_URL =
  'https://www.nuernberg-renegades.de/assets/forms/Mitgliedsantrag_26-10.pdf';

export const MEMBERSHIP_TYPES = ['adult', 'youth', 'support'] as const;
export type MembershipType = typeof MEMBERSHIP_TYPES[number];

/** Monthly fee in euros, as printed on the form. */
export const MEMBERSHIP_FEES: Record<MembershipType, number> = {
  adult: 18,
  youth: 15,
  support: 5,
};

export interface MembershipApplication {
  membership_type: MembershipType;
  name: string;
  firstname: string;
  birthday: string;
  birthplace: string;
  profession: string;
  nationality: string;
  street: string;
  plz_town: string;
  tel: string;
  fax: string;
  mobile: string;
  email: string;
  joindate_month: string;
  joindate_year: string;
  sepa_account_holder_name: string;
  sepa_account_holder_firstname: string;
  sepa_iban: string;
  sepa_bic: string;
  sepa_bank: string;
  recaptchaToken: string;
}

const GERMAN_MONTHS: Record<string, string> = {
  '01': 'Januar',
  '02': 'Februar',
  '03': 'März',
  '04': 'April',
  '05': 'Mai',
  '06': 'Juni',
  '07': 'Juli',
  '08': 'August',
  '09': 'September',
  '10': 'Oktober',
  '11': 'November',
  '12': 'Dezember',
};

/**
 * Fills the template's fields and flattens them, so the attachment prints as it looks.
 * `flatten: false` keeps the fields, for reading the values back in a test.
 */
export async function fillMembershipPdfForm(
  formPdfBytes: Uint8Array,
  application: MembershipApplication,
  { flatten = true } = {},
): Promise<Uint8Array> {
  const pdfDoc = await PDFDocument.load(formPdfBytes);
  const form = pdfDoc.getForm();
  const set = (name: string, value: string | undefined) =>
    form.getTextField(name).setText(value ?? '');

  // Each type box is a text field holding an X: that is what the paper form asks for, and
  // unlike a checkbox it needs no appearance stream of its own.
  if (!MEMBERSHIP_TYPES.includes(application.membership_type)) {
    throw new Error(`Unknown membership type: ${application.membership_type}`);
  }
  set(`membership_${application.membership_type}`, 'X');

  set('name', application.name);
  set('firstname', application.firstname);
  // ISO (YYYY-MM-DD) from the date input → DD.MM.YYYY
  const [year, month, day] = application.birthday.split('-');
  set('birthday', `${day}.${month}.${year}`);
  set('birthplace', application.birthplace);
  set('profession', application.profession);
  set('nationality', application.nationality);
  set('street', application.street);
  set('plz_town', application.plz_town);
  set('tel', application.tel);
  set('fax', application.fax);
  set('mobile', application.mobile);
  set('email', application.email);
  set('joindate_month', GERMAN_MONTHS[application.joindate_month]);
  // The form prints the "20"; only the last two digits go in.
  set('joindate_year', String(application.joindate_year).slice(-2));

  set('sepa_account_holder_name', application.sepa_account_holder_name);
  set('sepa_account_holder_firstname', application.sepa_account_holder_firstname);
  set('sepa_bank', application.sepa_bank);
  setBoxed(form, 'sepa_bic', application.sepa_bic);
  setBoxed(form, 'sepa_iban', application.sepa_iban);

  if (flatten) form.flatten();
  return await pdfDoc.save();
}

/**
 * The BIC and IBAN go one character per printed box (`sepa_iban_1` …). People type them with
 * spaces and in lower case, so those go; and a value with more characters than there are boxes
 * (a foreign IBAN can have up to 34) is printed as plain text across the row instead.
 */
function setBoxed(form: PDFForm, name: string, value: string | undefined) {
  const compact = (value ?? '').replace(/\s+/g, '').toUpperCase();
  const boxes: PDFTextField[] = [];
  for (let i = 1; form.getFieldMaybe(`${name}_${i}`); i++) boxes.push(form.getTextField(`${name}_${i}`));

  const row = form.getTextField(name);

  if (compact.length > boxes.length) {
    row.setText(compact.replace(/(.{4})(?=.)/g, '$1 '));
    return;
  }
  boxes.forEach((box, i) => box.setText(compact[i] ?? ''));
  // The row field is opaque so the dividers don't run through a long value; left in, it
  // would blank them out even when empty.
  form.removeField(row);
}
